using System.Text.Json;
using BotTraversal.Core;
using A=BotTraversal.Core.CapabilityFailureAction;
using F=BotTraversal.Core.FollowerCapabilityFailurePolicy;
using P=BotTraversal.Core.FollowerCapabilityApproachPolicy;
var checks=new List<string>();void Check(bool ok,string label){if(!ok)throw new Exception("FAIL "+label);checks.Add(label);}
bool Near(float a,float b)=>Math.Abs(a-b)<.00001f;
Check(F.Intercept(true,true,false),"current validated failure enters shared escalation");
Check(!F.Intercept(false,true,false),"retired probe cannot enter recovery");
Check(!F.Intercept(true,false,false),"unvalidated probe cannot borrow recovery");
Check(!F.Intercept(true,true,true),"already attempted terminal recovery cannot be rearmed by leaf");
Check(F.Initial(true,true,true,true,true)==A.Terminalize,"terminal one-shot outranks exhausted WalkThrough fallback");
Check(F.Initial(true,false,true,true,true)==A.Quarantine,"exhausted WalkThrough quarantines instead of fabricating teleport crossing");
Check(F.Initial(true,false,true,true,false)==A.Continue,"unexhausted WalkThrough retains existing escalation order");
Check(F.Initial(true,false,false,true,true)==A.Continue,"other abilities cannot inherit WalkThrough exhaustion");
Check(F.Initial(false,true,false,false,false)==A.Continue,"disabled historical single-shot flag retains legacy selection");
A Before(string kind="DropDown",bool rejected=true,bool drop=false,float epoch=-1,bool jump=false,string source="learningV32EntryAcquisitionFailed",bool isolate=true)=>F.BeforeExecution(isolate,kind,rejected,drop,epoch,jump,source);
Check(Before()==A.PreEntryRetry,"rejected DropDown before native epoch requests bounded retry");
Check(Before(source:"dropDownEntrySevereMismatch")==A.PreEntryRetry,"severe entry mismatch retains same retry category");
Check(Before(drop:true)==A.Continue,"actual DropDown attempt cannot masquerade as pre-entry failure");
Check(Before(epoch:0)==A.Continue,"started execution epoch cannot be erased by source label");
Check(Before(rejected:false)==A.Continue,"source string alone is not entry rejection proof");
Check(Before(isolate:false)==A.Continue,"disabled isolation flag preserves old escalation");
Check(Before(kind:"Jump",source:"learnedJumpTakeoffReadyTimeout")==A.PreActuatorRetry,"Jump before actuator retries without synthetic crossing");
Check(Before(kind:"jump",source:"learnedJumpTakeoffDirectionLost")==A.PreActuatorRetry,"case-insensitive Jump direction loss retains retry");
Check(Before(kind:"Jump",jump:true,source:"learnedJumpTakeoffReadyTimeout")==A.Continue,"actual Jump cannot reenter pre-actuator retry");
Check(Before(source:"unrelated")==A.Continue,"unrelated failure cannot borrow pre-entry isolation");
Check(Before(source:null!)==A.Continue,"null diagnostic reason cannot break failure selection");
Check(F.AfterExecution(true,"Jump",true,false)==A.NativeJumpRetry,"consumed native Jump cannot replay or teleport in same attempt");
Check(F.AfterExecution(true,"Jump",false,false)==A.AssistedReplay,"unconsumed Jump retains existing one assisted opportunity");
Check(F.AfterExecution(true,"Jump",true,true)==A.TerminalRecovery,"already assisted Jump cannot replay again");
Check(F.CanContinueNativeJump(true,false),"qualified native landing witness permits one existing ground continuation");
Check(!F.CanContinueNativeJump(false,false),"missing physical witness cannot grant ground continuation");
Check(!F.CanContinueNativeJump(true,true),"already retried native Jump cannot loop ground continuation");
foreach(string kind in new[]{"Climb","Vault","DropDown"}){
 Check(F.AfterExecution(true,kind,false,false)==A.AssistedReplay,"one assisted fallback remains available for "+kind);
 Check(F.AfterExecution(true,kind,false,true)==A.TerminalRecovery,"exhausted assist advances monotonically for "+kind);
}
Check(F.AfterExecution(true,"WalkThrough",false,false)==A.TerminalRecovery,"WalkThrough direct corridor does not gain second assisted executor");
Check(F.AfterExecution(false,"Jump",true,false)==A.AssistedReplay,"disabled historical single-trajectory flag retains old branch");
var plan=P.Jump(true,true,false,.5138962f,.3f,1f,.24f);
Check(plan.Active&&plan.Centering&&plan.Lateral<0,"recorded off-center substituted Jump can acquire a centering consumer");
Check(Near(plan.Speed,.24f),"centering requests existing bounded movement speed");
Check(plan.Forward>0&&plan.Forward<.02f,"centering keeps a small positive axis-facing tangent");
float length=MathF.Sqrt(plan.Forward*plan.Forward+plan.Lateral*plan.Lateral),forward=plan.Forward/length;
Check(Near(forward-FollowerCapabilityFrontierPolicy.ForwardRemoval(new(CapabilityFrontierKind.JumpPreparation,forward,0)),0),"existing native frontier still removes centering forward advance at preparation plane");
Check(P.Jump(true,true,false,.0473257f,.3f,1f,.24f).Active&&!P.Jump(true,true,false,.0473257f,.3f,1f,.24f).Centering,"recorded centered sample receives forward input without requiring prior facing success");
Check(!P.Jump(true,true,false,.8850714f,.3f,1f,.24f).Active,"far lateral sample cannot expand existing twice-corridor preparation region");
Check(!P.Jump(false,true,false,.4f,.3f,1f,.24f).Active,"airborne preparation cannot acquire centering input");
Check(!P.Jump(true,false,false,.4f,.3f,1f,.24f).Active,"remote centering cannot acquire native input");
Check(!P.Jump(true,true,true,.4f,.3f,1f,.24f).Active,"terminal recovery excludes centering consumer");
var geometry=new AdjacentLandingGeometry(.4011399f,.227805376f,.461f,.03739059f,2.2f,true,1.2f);
Check(FollowerCapabilityAdjacentLandingPolicy.LegacyRegion(geometry),"recorded first-chain miss remains inside existing steering region");
Check(P.Landing(true,true,true,true,true,true,1.9f,.8704475f,geometry.Ahead,geometry.VerticalError,geometry.AboveExit),"recorded off-axis first landing can select actual successor near-side direction");
Check(!FollowerCapabilityDropDownTransitionPolicy.Plan(new(DropDownConsumerPhase.Execute,true,true,true,1.9f,.8704475f,geometry.Ahead,geometry.Lateral,geometry.VerticalError,geometry.AboveExit,.08f,.42f)).Active,"native restraint corridor remains .20 rather than being widened to hide off-axis motion");
Check(!P.Landing(true,true,true,true,false,true,2,.8f,.4f,.1f,1),"accepted native path retains translation ownership");
Check(!P.Landing(false,true,true,true,true,true,2,.8f,.4f,.1f,1),"foreign probe cannot redirect input");
Check(!P.Landing(true,false,true,true,true,true,2,.8f,.4f,.1f,1),"unrelated stage cannot redirect landing input");
Check(!P.Landing(true,true,false,true,true,true,2,.8f,.4f,.1f,1),"no native attempt cannot acquire landing direction");
Check(!P.Landing(true,true,true,false,true,true,2,.8f,.4f,.1f,1),"other capabilities cannot borrow dropdown approach");
Check(!P.Landing(true,true,true,true,true,false,2,.8f,.4f,.1f,1),"off-corridor successor does not create navigation");
Check(!P.Landing(true,true,true,true,true,true,.7f,.8f,.4f,.1f,1),"near side of predecessor retains original approach");
Check(!P.Landing(true,true,true,true,true,true,2,.8f,-.363443375f,.1f,1),"recorded overrun cannot be rewound by target selection");
Check(!P.Landing(true,true,true,true,true,true,2,.8f,.025f,.1f,1),"reached near-side plane releases direction rewrite to existing boundary");
Check(!P.Landing(true,true,true,true,true,true,2,.8f,.4f,.301f,1),"lower-level geometry cannot borrow upper steering");
Check(!P.Landing(true,true,true,true,true,true,2,.8f,.4f,.1f,.399f),"near lower exit cannot masquerade as upper approach");
foreach(float bad in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity}){
 Check(!P.Jump(true,true,false,bad,.3f,1,.24f).Active,"invalid centering observation rejected "+bad);
 Check(!P.Landing(true,true,true,true,true,true,bad,.8f,.4f,.1f,1),"invalid progress cannot redirect native input "+bad);
}
File.WriteAllText(args[0],JsonSerializer.Serialize(new{passed=true,checks=checks.Count,cases=checks,physicsSimulated=false},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS {checks.Count} compiled capability failure and approach checks");
